// Update allows overriding fields `UPDATE` values. See the RiderProfileCreateBulk.OnConflict
// documentation for more info.
func (u *RiderProfileUpsertBulk) Update(set func(*RiderProfileUpsert)) *RiderProfileUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&RiderProfileUpsert{UpdateSet: update})
	}))
	return u
}

